content.query:
// Proxy for 'Next 6 Months Finding Grade Evolution':
// current severity distribution of in-flight findings.
BitSightFindingsData
| where RiskVectorLabel == 'Desktop Software'
| summarize ['Finding Count'] = count() by SeverityCategory
| order by SeverityCategory asc

// Proxy for 'Next 6 Months Finding Grade Evolution':
// current severity distribution of in-flight findings.
BitSightFindingsData
| where RiskVectorLabel == 'Mobile Software'
| summarize ['Finding Count'] = count() by SeverityCategory
| order by SeverityCategory asc
